#!/usr/bin/env python3

# ----------------------------------------------------------------------
# Usage: python read_pcap.py capture.pcap
# Reads PCAP files generated by live_monitor.py
#
# Vectorized packet parse.
# Returns per-packet timestamps (from Scapy).
# Reports ADC clipping statistics automatically.
#
# Auto-detects NFFT / bandwidth from the Nexmon CSI chanspec field,
# with a packet-length fallback.  Supports 20, 40, 80, and 160 MHz.
# ----------------------------------------------------------------------

import sys
import numpy as np
from pathlib import Path
from scapy.all import rdpcap


# ------------------------------------------------------------------
# Clipping check (shared utility)
# ------------------------------------------------------------------

def check_clipping(csi_data, threshold=32000, verbose=True):
    """Report clipping statistics for a CSI array."""
    re = np.asarray(csi_data.real)
    im = np.asarray(csi_data.imag)

    total = re.size + im.size
    if total == 0:
        if verbose:
            print("Clipping report: no samples")
        return 0

    re_clipped = int(np.sum(np.abs(re) >= threshold))
    im_clipped = int(np.sum(np.abs(im) >= threshold))
    clipped = re_clipped + im_clipped
    pct = 100.0 * clipped / total

    if verbose:
        print("Clipping report:")
        print(f"  Threshold      : |x| >= {threshold}")
        print(f"  Total samples  : {total}")
        print(f"  |re| clipped   : {re_clipped} ({100.0 * re_clipped / total:.4f}%)")
        print(f"  |im| clipped   : {im_clipped} ({100.0 * im_clipped / total:.4f}%)")
        print(f"  Total clipped  : {clipped} ({pct:.4f}%)")
        print(f"  Max |re|       : {float(np.max(np.abs(re))):.1f}")
        print(f"  Max |im|       : {float(np.max(np.abs(im))):.1f}")

        if pct > 0.01:
            print("  WARNING: significant clipping — "
                  "reduce RX gain or increase TX-RX distance")
        elif pct > 0.0001:
            print("  WARNING: minor clipping — "
                  "may distort small modulations")
        else:
            print("  OK: no significant clipping")

    return clipped


# ------------------------------------------------------------------
# Bandwidth / NFFT detection helpers
# ------------------------------------------------------------------

# Nexmon CSI chanspec encoding — bits 8-15 of the 16-bit chanspec word
# contain the bandwidth code.  These are the values seen in practice
# on bcm43455c0 and friends.
_CHANSPEC_BW_TO_NFFT = {
    0x00: 64,    # 20 MHz
    0x01: 64,    # 20 MHz (alt)
    0x02: 128,   # 40 MHz
    0x03: 128,   # 40 MHz (alt)
    0x04: 256,   # 80 MHz
    0x05: 256,   # 80 MHz (alt)
    0x06: 512,   # 160 MHz
}

# Fallback mapping from payload byte length to NFFT.
# 15 uint32 words of header + NFFT uint32 words of CSI = (15+NFFT)*4 bytes.
# We round to the nearest supported NFFT value.
_SUPPORTED_NFFT = [64, 128, 256, 512]


def _detect_nfft_from_chanspec(chanspec):
    """Return NFFT for a chanspec word, or None if unknown."""
    # Chanspec format (Nexmon): bw code in bits 8-15.
    bw_code = (chanspec >> 8) & 0xFF

    # Direct hit on common values.
    if bw_code in _CHANSPEC_BW_TO_NFFT:
        return _CHANSPEC_BW_TO_NFFT[bw_code]

    # Looser check: mask off the top nibble only.
    bw_nibble = bw_code & 0xF0
    if bw_nibble == 0x00:
        return 64
    if bw_nibble == 0x10:
        return 128
    if bw_nibble == 0xE0:
        return 256

    return None


def _detect_nfft_from_length(payload_len_bytes):
    """
    Infer NFFT from how many bytes are actually present after the
    15-word header.
    """
    total_words = payload_len_bytes // 4
    csi_words = total_words - 15

    if csi_words <= 0:
        return None

    # Pick the supported NFFT that is closest to and no larger than
    # what's available.
    candidates = [n for n in _SUPPORTED_NFFT if n <= csi_words]
    if not candidates:
        return None

    return max(candidates)


# ------------------------------------------------------------------
# Configuration (kept for backward compatibility)
# ------------------------------------------------------------------

class PCAPConfig:
    """
    Configuration for PCAP parsing.

    NFFT is now auto-detected from the first packet.  BW is only used
    as a fallback if detection fails, and NFFT is left as None to
    signal "detect from data".
    """
    HOFFSET = 15          # Offset for CSI data in packet (uint32 words)
    BW = 80               # Fallback bandwidth in MHz
    NFFT = None           # None = auto-detect


# ------------------------------------------------------------------
# PCAP loader
# ------------------------------------------------------------------

class PCAPDataLoader:
    """Load and parse CSI data from PCAP files."""

    def __init__(self, pcap_file, config=None):
        self.pcap_file = pcap_file
        self.config = config if config else PCAPConfig()
        self.csi_data = None
        self.csi_timestamps = None
        self.metadata = None

    def load(self):
        """Load PCAP and extract CSI data."""
        if not Path(self.pcap_file).exists():
            raise FileNotFoundError(f"File '{self.pcap_file}' not found!")

        print(f"Reading PCAP file: {self.pcap_file}")

        packets = rdpcap(self.pcap_file)
        print(f"Total packets in PCAP: {len(packets)}")

        if len(packets) == 0:
            raise ValueError("PCAP contains no packets")

        hoffset = self.config.HOFFSET

        # ------------------------------------------------------------
        # Pass 1: read enough bytes from each packet to detect NFFT.
        # We can't know NFFT yet, so grab the full raw payload and
        # work out the correct truncation later.
        # ------------------------------------------------------------
        raw_payloads_full = []
        pkt_times = []

        for pkt in packets:
            raw = bytes(pkt)

            # Need at least the header + a few CSI words.
            min_header_bytes = (hoffset + 1) * 4
            if len(raw) < min_header_bytes:
                continue

            raw_payloads_full.append(raw)

            try:
                pkt_times.append(float(pkt.time))
            except Exception:
                pkt_times.append(np.nan)

        if not raw_payloads_full:
            raise ValueError(
                "No packets long enough to contain Nexmon CSI metadata"
            )

        # ------------------------------------------------------------
        # Detect NFFT.
        # Priority:
        #   1. Explicit override in config.
        #   2. Chanspec field of the first packet.
        #   3. Length of the first packet's payload.
        # ------------------------------------------------------------
        nfft = None

        if self.config.NFFT is not None:
            nfft = int(self.config.NFFT)
            print(f"NFFT: {nfft} (from config override)")

        first = raw_payloads_full[0]

        if nfft is None:
            chanspec = int.from_bytes(first[56:58], "little")
            detected = _detect_nfft_from_chanspec(chanspec)
            if detected is not None:
                nfft = detected
                print(
                    f"NFFT: {nfft} "
                    f"(from chanspec=0x{chanspec:04X})"
                )

        if nfft is None:
            detected = _detect_nfft_from_length(len(first))
            if detected is not None:
                nfft = detected
                print(
                    f"NFFT: {nfft} "
                    f"(inferred from payload length {len(first)} bytes)"
                )

        if nfft is None:
            raise ValueError(
                "Could not determine NFFT from chanspec or payload length. "
                f"First packet is {len(first)} bytes long."
            )

        need_words = hoffset + nfft
        need_bytes = need_words * 4

        print(f"Using HOFFSET={hoffset}, NFFT={nfft}, "
              f"need_bytes={need_bytes}")

        # ------------------------------------------------------------
        # Pass 2: truncate each packet to need_bytes and keep only
        # those that are long enough.
        # ------------------------------------------------------------
        raw_payloads = []

        for raw in raw_payloads_full:
            if len(raw) < need_bytes:
                continue
            raw_payloads.append(raw[:need_bytes])

        valid_packets = len(raw_payloads)
        if valid_packets == 0:
            raise ValueError(
                f"No packets with at least {need_bytes} bytes "
                f"(NFFT={nfft}).  Check that the capture bandwidth "
                f"matches the packet format."
            )

        # Trim timestamps to match the surviving packets.
        # We need to know which ones survived.  Rebuild in sync:
        pkt_times_kept = []
        idx = 0
        for raw in raw_payloads_full:
            if len(raw) >= need_bytes:
                pkt_times_kept.append(pkt_times[idx])
            idx += 1
        pkt_times = pkt_times_kept

        # ------------------------------------------------------------
        # Bulk-convert.
        # ------------------------------------------------------------
        big = np.frombuffer(
            b"".join(raw_payloads), dtype="<u4"
        ).reshape(valid_packets, need_words)

        H = big[:, hoffset:hoffset + nfft].copy()
        hout = H.view(np.int16).reshape(valid_packets, nfft, 2)

        complex_csi = (
            hout[:, :, 0].astype(np.float64)
            + 1j * hout[:, :, 1].astype(np.float64)
        )

        # ------------------------------------------------------------
        # Timestamps.
        # ------------------------------------------------------------
        ts = np.asarray(pkt_times, dtype=float)

        if not np.all(np.isfinite(ts)):
            print("Warning: some PCAP timestamps missing; using synthetic grid")
            ts = np.arange(valid_packets) / 93.5

        if np.any(np.diff(ts) <= 0):
            order = np.argsort(ts)
            ts = ts[order]
            complex_csi = complex_csi[order]

        # ------------------------------------------------------------
        # Metadata.
        # ------------------------------------------------------------
        metadata = {}
        first = raw_payloads[0]
        metadata['sequence'] = int.from_bytes(first[52:54], "little")
        core_ss = int.from_bytes(first[54:56], "little")
        metadata['core'] = core_ss & 0x7
        metadata['nss'] = (core_ss >> 3) & 0x7
        metadata['chanspec'] = int.from_bytes(first[56:58], "little")
        metadata['chipver'] = int.from_bytes(first[58:60], "little")
        metadata['n_subcarriers'] = nfft

        # Try to record the bandwidth in MHz for reporting.
        bw_mhz = {64: 20, 128: 40, 256: 80, 512: 160}.get(nfft, None)
        metadata['bandwidth'] = bw_mhz if bw_mhz is not None else self.config.BW

        self.csi_data = complex_csi
        self.csi_timestamps = ts

        duration = float(ts[-1] - ts[0]) if len(ts) > 1 else 0.0

        metadata['n_packets'] = complex_csi.shape[0]
        metadata['n_subcarriers'] = complex_csi.shape[1]
        metadata['first_ts'] = float(ts[0])
        metadata['last_ts'] = float(ts[-1])
        metadata['duration'] = duration
        metadata['rate'] = (
            (len(ts) - 1) / duration
            if duration > 0
            else 0.0
        )
        metadata['timestamps'] = ts

        self.metadata = metadata

        # ------------------------------------------------------------
        # Summary
        # ------------------------------------------------------------
        print(f"\nExtracted {valid_packets} valid CSI packets")
        print(f"CSI data shape: {self.csi_data.shape}")
        print(f"  Bandwidth  = {metadata['bandwidth']} MHz")
        print(f"  Duration   = {duration:.3f} s")
        print(f"  Rate       = {metadata['rate']:.3f} Hz")
        print(f"  Min I value = {self.csi_data.real.min():.2f}")
        print(f"  Max I value = {self.csi_data.real.max():.2f}")
        print(f"  Min Q value = {self.csi_data.imag.min():.2f}")
        print(f"  Max Q value = {self.csi_data.imag.max():.2f}")

        check_clipping(self.csi_data, verbose=True)

        if self.csi_data.shape[0] > 0:
            magnitudes = np.abs(self.csi_data)
            idx_pkt = min(99, self.csi_data.shape[0] - 1)
            strongest_idx = np.argsort(magnitudes[idx_pkt])[::-1][:15]

            print(f"\n15 Strongest Subcarriers (packet {idx_pkt + 1})")
            print("-" * 60)
            print(f"{'Subcarrier':<12} {'Magnitude':<12} {'I':<12} {'Q':<12}")
            print("-" * 60)
            for i in strongest_idx:
                print(
                    f"{i:>5}      {magnitudes[idx_pkt, i]:>10.2f}  "
                    f"{self.csi_data[idx_pkt, i].real:>10.2f}  "
                    f"{self.csi_data[idx_pkt, i].imag:>10.2f}"
                )

        return self.csi_data, self.metadata


def load_pcap_csi(pcap_file):
    """Convenience function to load CSI data from PCAP"""
    loader = PCAPDataLoader(pcap_file)
    return loader.load()


def extract_csi_info(pcap_file):
    """Original function from read_pcap.py - for backward compatibility"""
    loader = PCAPDataLoader(pcap_file)
    csi_data, metadata = loader.load()

    print("\n" + "="*60)
    print("CSI Analysis Complete")
    print("="*60)

    return csi_data, metadata


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} capture.pcap")
        print("\nThis script reads PCAP files generated by live_monitor.py")
        sys.exit(1)

    try:
        csi_data, metadata = load_pcap_csi(sys.argv[1])
        print(f"\nSuccessfully loaded {metadata['n_packets']} packets")
        print(f"with {metadata['n_subcarriers']} subcarriers each")
        print(f"Bandwidth: {metadata.get('bandwidth', 'N/A')} MHz")
        print(f"Duration: {metadata['duration']:.3f} s")
        print(f"Rate: {metadata['rate']:.2f} Hz")
        print(f"Core: {metadata.get('core', 'N/A')}")
        print(f"NSS: {metadata.get('nss', 'N/A')}")
        print(f"Chanspec: 0x{metadata.get('chanspec', 0):04X}")
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)